SELECT CAST(SUM(CASE WHEN T2.remaining < 0 THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(T2.event_id) AS percentage_over_budget
FROM event AS T1
JOIN budget AS T2 ON T1.event_id = T2.link_to_event;

SELECT SUM(CASE WHEN T2.A3 = 'East Bohemia' THEN T2.A16 ELSE 0 END) - SUM(CASE WHEN T2.A3 = 'North Bohemia' THEN T2.A16 ELSE 0 END) AS crime_difference
FROM district AS T2
JOIN loan AS T1 ON T2.district_id = T1.account_id;

